				type: "spring",
				duration: 0.3,
				bounce: 0,
			}}
			{...props}
		/>
	);
}

src/registry/components/interactive-spri:
"use client";

import type { CSSProperties } from "react";
import { useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

type SpriteFrame = {
	column: number;
	row: number;
};

type Direction =
	| "center"
	| "east"
	| "north"
	| "north-east"
	| "north-west"
	| "south"
	| "south-east"
	| "south-west"
	| "west";

export type DirectionFrameMap = Record<Direction, SpriteFrame>;

export type InteractiveSpriteProps = {
	/** Accessible description for the character. Use an empty string when decorative. */
	alt: string;
	/** Number of equally sized columns in the sprite sheet. */
	columns?: number;
	/** Distance from the character's center that keeps the resting frame active. */
	deadZone?: number;
	/** Maps pointer directions to cells in the sprite sheet. */
	frames?: DirectionFrameMap;
	/** Time without pointer movement before returning to the center frame. */
	idleDelay?: number;
	/** Number of equally sized rows in the sprite sheet. */
	rows?: number;
	/** Public URL for the sprite sheet. */
	src: string;
	className?: string;
	style?: CSSProperties;
};

const DEFAULT_FRAMES: DirectionFrameMap = {
	"north-west": { column: 0, row: 0 },
	north: { column: 1, row: 0 },
	"north-east": { column: 2, row: 0 },
	west: { column: 0, row: 1 },
	center: { column: 1, row: 1 },
	east: { column: 2, row: 1 },
	"south-west": { column: 0, row: 2 },
	south: { column: 1, row: 2 },
	"south-east": { column: 2, row: 2 },
};

const OCTANTS: Direction[] = [
	"east",
	"south-east",
	"south",
	"south-west",
	"west",
	"north-west",
	"north",
	"north-east",
];

function getDirection(deltaX: number, deltaY: number, deadZone: number) {
	if (Math.hypot(deltaX, deltaY) <= deadZone) return "center";

	const octant =
		(Math.round(Math.atan2(deltaY, deltaX) / (Math.PI / 4)) + 8) % 8;

	return OCTANTS[octant];
}

function getBackgroundPosition(
	frame: SpriteFrame,
	columns: number,
	rows: number,
) {
	const x = columns === 1 ? 0 : (frame.column / (columns - 1)) * 100;
	const y = rows === 1 ? 0 : (frame.row / (rows - 1)) * 100;

	return `${x}% ${y}%`;
}

export function InteractiveSprite({
	alt,
	className,
	columns = 3,
	deadZone = 24,
	frames = DEFAULT_FRAMES,
	idleDelay = 300,
	rows = 3,
	src,
	style,
}: InteractiveSpriteProps) {
	const rootRef = useRef<HTMLSpanElement>(null);
	const activeDirectionRef = useRef<Direction>("center");
	const [activeDirection, setActiveDirection] = useState<Direction>("center");

	useEffect(() => {
		const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
		let animationFrame: number | null = null;
		let idleTimeout: number | undefined;

		const resetDirection = () => {
			if (activeDirectionRef.current === "center") return;

			activeDirectionRef.current = "center";
			setActiveDirection("center");
		};

		const handlePointerMove = (event: PointerEvent) => {
			if (event.pointerType === "touch" || reducedMotion.matches) return;

			window.clearTimeout(idleTimeout);
			if (animationFrame !== null) cancelAnimationFrame(animationFrame);

			animationFrame = requestAnimationFrame(() => {
				animationFrame = null;
				const root = rootRef.current;
				if (!root || reducedMotion.matches) return;

				const bounds = root.getBoundingClientRect();
				const direction = getDirection(
					event.clientX - (bounds.left + bounds.width / 2),
					event.clientY - (bounds.top + bounds.height / 2),
					deadZone,
				);

				if (direction !== activeDirectionRef.current) {
					activeDirectionRef.current = direction;
					setActiveDirection(direction);
				}

				idleTimeout = window.setTimeout(resetDirection, idleDelay);
			});
		};

		const handleMotionPreferenceChange = () => {
			if (reducedMotion.matches) resetDirection();
		};

		window.addEventListener("pointermove", handlePointerMove, {
			passive: true,
		});
		reducedMotion.addEventListener("change", handleMotionPreferenceChange);

		return () => {
			window.removeEventListener("pointermove", handlePointerMove);
			reducedMotion.removeEventListener("change", handleMotionPreferenceChange);
			window.clearTimeout(idleTimeout);
			if (animationFrame !== null) cancelAnimationFrame(animationFrame);
		};
	}, [deadZone, idleDelay]);

	const frame = frames[activeDirection];
	const spriteStyle: CSSProperties = {
		backgroundImage: `url("${src}")`,
		backgroundPosition: getBackgroundPosition(frame, columns, rows),
		backgroundRepeat: "no-repeat",
		backgroundSize: `${columns * 100}% ${rows * 100}%`,
	};
	const accessibilityProps = alt
		? { "aria-label": alt, role: "img" }
		: { "aria-hidden": true as const };

	return (
		<span
			ref={rootRef}
			className={cn("block overflow-hidden", className)}
			data-direction={activeDirection}
			data-slot="interactive-sprite"
			style={style}
			{...accessibilityProps}
		>
			<span
				aria-hidden="true"
				className="block size-full"
				style={spriteStyle}
			/>
		</span>
	);
}

export default InteractiveSprite;

src/registry/components/peeping-button/p:
"use client";

import {
	MotionConfig,
	motion,
	useMotionTemplate,
	useMotionValue,
	useReducedMotion,
	useSpring,
} from "motion/react";
import {
	type ComponentPropsWithoutRef,
	type FocusEvent,
	forwardRef,
	type PointerEvent as ReactPointerEvent,
	useCallback,
	useEffect,
	useRef,
	useState,
} from "react";

import { cn } from "@/lib/utils";

export interface PeepingButtonProps extends ComponentPropsWithoutRef<"button"> {
	/** Classes applied to the hinged, visible face of the button. */
	coverClassName?: string;
	/** Delay before each peek, or a random range in milliseconds. */
	peekDelay?: number | readonly [min: number, max: number];
	/** How long the eyes remain visible in milliseconds. */
	peekDuration?: number;
	/** Disable the automatic peeking behavior while keeping a usable button. */
	autoPeek?: boolean;
}

const DEFAULT_PEEK_DELAY = [2800, 5200] as const;
const DEFAULT_PEEK_DURATION = 2200;

function resolvePeekDelay(min: number, max: number) {
	return min + Math.random() * (max - min);
}

export const PeepingButton = forwardRef<HTMLButtonElement, PeepingButtonProps>(
	(
		{
			autoPeek = true,
			children,
			className,
			coverClassName,
			disabled,
			onBlur,
			onFocus,
			onPointerEnter,
			onPointerLeave,
			peekDelay = DEFAULT_PEEK_DELAY,
			peekDuration = DEFAULT_PEEK_DURATION,
			type = "button",
			...props
		},
		ref,
	) => {
		const eyesRef = useRef<HTMLSpanElement>(null);
		const [autoOpen, setAutoOpen] = useState(false);
		const [isEngaged, setIsEngaged] = useState(false);
		const [isPageVisible, setIsPageVisible] = useState(true);
		const reduceMotion = useReducedMotion();

		const pupilX = useMotionValue(0);
		const pupilY = useMotionValue(0);
		const smoothPupilX = useSpring(pupilX, {
			duration: 0.35,
			bounce: 0.16,
		});
		const smoothPupilY = useSpring(pupilY, {
			duration: 0.35,
			bounce: 0.16,
		});
		const pupilTransform = useMotionTemplate`translate3d(calc(-50% + ${smoothPupilX}px), calc(-50% + ${smoothPupilY}px), 0)`;
		const peekDelayStart =
			typeof peekDelay === "number" ? peekDelay : peekDelay[0];
		const peekDelayEnd =
			typeof peekDelay === "number" ? peekDelay : peekDelay[1];
		const peekDelayMin = Math.min(peekDelayStart, peekDelayEnd);
		const peekDelayMax = Math.max(peekDelayStart, peekDelayEnd);

		const canPeek =
			autoPeek && !disabled && isPageVisible && reduceMotion !== true;
		const isOpen = canPeek && autoOpen && !isEngaged;

		useEffect(() => {
			function handleVisibilityChange() {
				const visible = document.visibilityState === "visible";
				setIsPageVisible(visible);
				if (!visible) setAutoOpen(false);
			}

			handleVisibilityChange();
			document.addEventListener("visibilitychange", handleVisibilityChange);
			return () =>
				document.removeEventListener(
					"visibilitychange",
					handleVisibilityChange,
				);
		}, []);

		useEffect(() => {
			if (!canPeek || isEngaged) {
				setAutoOpen(false);
				return;
			}

			const timeout = window.setTimeout(
				() => setAutoOpen((open) => !open),
				autoOpen ? peekDuration : resolvePeekDelay(peekDelayMin, peekDelayMax),
			);

			return () => window.clearTimeout(timeout);
		}, [
			autoOpen,
			canPeek,
			isEngaged,
			peekDelayMax,
			peekDelayMin,
			peekDuration,
		]);

		const pointEyesAt = useCallback(
			(clientX: number, clientY: number) => {
				const eyes = eyesRef.current;
				if (!eyes) return;

				const bounds = eyes.getBoundingClientRect();
				const deltaX = clientX - (bounds.left + bounds.width / 2);
				const deltaY = clientY - (bounds.top + bounds.height / 2);
				const distance = Math.hypot(deltaX, deltaY);
				const strength = Math.min(distance / 240, 1);
				const angle = Math.atan2(deltaY, deltaX);

				pupilX.set(Math.cos(angle) * 2.25 * strength);
				pupilY.set(Math.sin(angle) * 1.75 * strength);
			},
			[pupilX, pupilY],
		);

		useEffect(() => {
			if (!isOpen) {
				pupilX.set(0);
				pupilY.set(0);
				return;
			}

			function handlePointerMove(event: PointerEvent) {
				if (event.pointerType === "touch") return;
				pointEyesAt(event.clientX, event.clientY);
			}

			window.addEventListener("pointermove", handlePointerMove, {
				passive: true,
			});
			return () => window.removeEventListener("pointermove", handlePointerMove);
		}, [isOpen, pointEyesAt, pupilX, pupilY]);

		function handlePointerEnter(event: ReactPointerEvent<HTMLButtonElement>) {
			onPointerEnter?.(event);
			if (!event.defaultPrevented && event.pointerType !== "touch") {
				setIsEngaged(true);
			}
		}

		function handlePointerLeave(event: ReactPointerEvent<HTMLButtonElement>) {
			onPointerLeave?.(event);
			if (!event.defaultPrevented) setIsEngaged(false);
		}

		function handleFocus(event: FocusEvent<HTMLButtonElement>) {
			onFocus?.(event);
			if (!event.defaultPrevented) setIsEngaged(true);
		}

		function handleBlur(event: FocusEvent<HTMLButtonElement>) {
			onBlur?.(event);
			if (!event.defaultPrevented) setIsEngaged(false);
		}

		return (
			<MotionConfig reducedMotion="user">
				<button
					ref={ref}
					type={type}
					data-slot="peeping-button"
					data-peeking={isOpen ? "true" : "false"}
					disabled={disabled}
					onBlur={handleBlur}
					onFocus={handleFocus}
					onPointerEnter={handlePointerEnter}
					onPointerLeave={handlePointerLeave}
					className={cn(
						"group/peeping-button relative inline-grid min-w-36 touch-manipulation select-none place-items-center rounded-lg bg-muted text-sm outline-none",
						"transition-transform duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] active:scale-[0.97] motion-reduce:transform-none motion-reduce:transition-none",
						"focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50",
						className,
					)}
					{...props}
				>
					<span
						ref={eyesRef}
						aria-hidden="true"
						className="pointer-events-none absolute right-[0.9em] bottom-[0.55em] flex items-center gap-[0.35em]"
					>
						{["left", "right"].map((eye) => (
							<motion.span
								key={eye}
								className="relative size-[0.72em] overflow-hidden rounded-full bg-foreground"
								animate={
									reduceMotion === true || !isOpen
										? { transform: "scaleY(1)" }
										: {
												transform: [
													"scaleY(1)",
													"scaleY(1)",
													"scaleY(0.12)",
													"scaleY(1)",
												],
											}
								}
								transition={{
									duration: 4,
									times: [0, 0.92, 0.96, 1],
									repeat: Number.POSITIVE_INFINITY,
									ease: "linear",
								}}
							>
								<motion.span
									className="absolute top-1/2 left-1/2 size-[0.34em] rounded-full bg-background"
									style={{ transform: pupilTransform }}
								/>
							</motion.span>
						))}
					</span>

					<motion.span
						className={cn(
							"pointer-events-none absolute inset-0 flex origin-[1.25em_50%] items-center justify-center rounded-[inherit] border border-border bg-card px-5 py-3 font-medium text-card-foreground shadow-xs",
							coverClassName,
						)}
						animate={{
							transform: isOpen ? "rotate(-11deg)" : "rotate(0deg)",
						}}
						transition={
							isOpen
								? { type: "spring", duration: 0.45, bounce: 0.18 }
								: {
										duration: 0.2,
										ease: [0.23, 1, 0.32, 1],
									}
						}
					>
						{children}
					</motion.span>

					<span
						aria-hidden="true"
						className="invisible block px-5 py-3 font-medium"
					>
						{children}
					</span>
				</button>
			</MotionConfig>
		);
	},
);

PeepingButton.displayName = "PeepingButton";

export default PeepingButton;

